def chain_follower(chain):
    chain_dict = {}
    for token in chain:
        if token not in chain_dict:
            chain_dict[token] = []

    current = chain_dict[chain[0]]
    result = []

    while current:
        result.append(current.pop(0))
        next_token = current[0]
        if next_token in chain_dict:
            current = chain_dict[next_token]
        else:
            current = None

    return ','.join(result)
